import{R as e,e as o,f as a,U as n}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Zapier","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/zapier.md","filePath":"integrations/automations/zapier.md","lastUpdated":1775908585000}'),r={name:"integrations/automations/zapier.md"};function i(s,t,l,p,h,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="zapier" tabindex="-1">Zapier <a class="header-anchor" href="#zapier" aria-label="Permalink to &quot;Zapier&quot;">​</a></h1><p>Follow the below steps to connect to the Zapier API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Zapier</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-zapier-api" tabindex="-1">Step 2. Connect to the Zapier API <a class="header-anchor" href="#step-2-connect-to-the-zapier-api" aria-label="Permalink to &quot;Step 2. Connect to the Zapier API&quot;">​</a></h3><ol><li>Go to <a href="https://zapier.com/app/zaps" target="_blank">Zapier</a> and create a new Zap.</li><li>For the <strong>Choose App &amp; Event</strong> value, enter <strong>Webhooks by Zapier</strong>.</li><li>For the <strong>Choose Trigger Event</strong> value, enter <strong>Catch Hook</strong>.</li><li>Click <strong>Continue</strong>.</li><li>Copy the <strong>Custom Webhook URL</strong> into the <strong>Webhook</strong> field in Formie.</li></ol><h3 id="step-3-form-setting-test-payload" tabindex="-1">Step 3. Form Setting &amp; Test Payload <a class="header-anchor" href="#step-3-form-setting-test-payload" aria-label="Permalink to &quot;Step 3. Form Setting &amp; Test Payload&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol>',8)])])}const m=e(r,[["render",i]]);export{d as __pageData,m as default};
